#!/bin/bash
# Print the three most frequent IPs in access.log, one per line,
# most frequent first; ties broken by first appearance in the log.
set -eu
awk '
{
    ip = $1
    count[ip]++
    if (!(ip in first_seen)) {
        first_seen[ip] = NR
        order[++n] = ip
    }
}
END {
    # Stable sort by count descending; awk lacks a stable sort, so
    # use index in first appearance as the tiebreaker explicitly.
    for (i = 1; i <= n && i <= 3; i++) {
        best = order[i]
        for (j = i + 1; j <= n; j++) {
            if (count[order[j]] > count[best]) best = order[j]
        }
        print best
    }
}
' access.log
